    function clearMessages() {
      errorMessage.textContent = "";
      statusMessage.textContent = "";
      statusMessage.className = "status-message";
      radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
    }

    function showError(message) {
      errorMessage.textContent = message;
      statusMessage.textContent = message;
      statusMessage.className = "status-message error";
      radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
      radios[0].focus();
    }

    function showSuccess(message) {
      statusMessage.textContent = message;
      statusMessage.className = "status-message success";
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      clearMessages();

      const selectedRadio = radios.find((radio) => radio.checked);

      if (!selectedRadio) {
        showError("Error: Choose how you prefer to receive notifications.");
        return;
      }

      showSuccess("Preference saved: " + selectedRadio.value + ".");
    });

    radios.forEach((radio) => {
      radio.addEventListener("change", () => {
        clearMessages();
      });
