   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Notification Preferences</h1>
       <p class="intro">Choose how you would like to receive updates from us.</p>
       <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

       <form id="notification-form" novalidate>
         <p id="form-status" class="status-message" aria-live="polite"></p>

         <div class="form-field">
           <fieldset id="notification-group" aria-describedby="notification-help notification-error">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-indicator" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="help-text">Select one option before submitting the form.</p>

             <div class="radio-list">
               <label class="radio-option" for="notify-email">
                 <input id="notify-email" name="notificationPreference" type="radio" value="Email" required>
                 <span>Email</span>
               </label>

               <label class="radio-option" for="notify-sms">
                 <input id="notify-sms" name="notificationPreference" type="radio" value="SMS" required>
                 <span>SMS</span>
               </label>

               <label class="radio-option" for="notify-push">
                 <input id="notify-push" name="notificationPreference" type="radio" value="Push Notifications" required>
                 <span>Push Notifications</span>
               </label>
             </div>

             <p id="notification-error" class="field-error" role="alert"></p>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const radios = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
     const errorMessage = document.getElementById("notification-error");
     const statusMessage = document.getElementById("form-status");

     function clearMessages() {
       errorMessage.textContent = "";
       statusMessage.textContent = "";
       statusMessage.className = "status-message";
       radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
     }

     function showError(message) {
       errorMessage.textContent = message;
       statusMessage.textContent = message;
       statusMessage.className = "status-message error";
       radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
       radios[0].focus();
     }

     function showSuccess(message) {
       statusMessage.textContent = message;
       statusMessage.className = "status-message success";
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       clearMessages();

       const selectedRadio = radios.find((radio) => radio.checked);

       if (!selectedRadio) {
         showError("Error: Choose how you prefer to receive notifications.");
         return;
       }

       showSuccess("Preference saved: " + selectedRadio.value + ".");
     });

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         clearMessages();
       });
     });
   </script>
